create or replace function public.shop_update_order_status(p_order_id uuid,p_status text) returns public.shop_orders language plpgsql security definer set search_path=public as $$declare v_staff public.staff%rowtype; v_order public.shop_orders%rowtype; v_item record; begin select * into v_staff from public.staff where id=auth.uid() and is_active=true; if not found then raise exception 'Staff access required'; end if; if p_status not in ('pending','confirmed','packed','in_transit','delivered','cancelled') then raise exception 'Invalid order status'; end if; select * into v_order from public.shop_orders where id=p_order_id for update; if not found then raise exception 'Order not found'; end if; if v_order.status='cancelled' and p_status<>'cancelled' then raise exception 'Cancelled order cannot be reopened'; end if; if p_status='cancelled' and v_order.status<>'cancelled' then for v_item in select product_id,quantity from public.shop_order_items where order_id=p_order_id loop update public.shop_products set reserved_count=greatest(0,reserved_count-v_item.quantity),updated_at=now() where id=v_item.product_id; end loop; end if; update public.shop_orders set status=p_status,updated_at=now() where id=p_order_id returning * into v_order; return v_order; end; $$;
revoke all on function public.shop_update_order_status(uuid,text) from public,anon,authenticated; grant execute on function public.shop_update_order_status(uuid,text) to authenticated;
